// No API, credential, signal or price caching. Push actions only open authenticated review.
self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
function database(){return new Promise((resolve,reject)=>{const r=indexedDB.open('tradeomatic-delivery-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('seen',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function seen(id,write=false){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('seen',write?'readwrite':'readonly'),store=tx.objectStore('seen'),r=write?store.put({id,time:Date.now()}):store.get(id);r.onsuccess=()=>resolve(write?true:!!r.result);r.onerror=()=>reject(r.error);tx.oncomplete=()=>db.close()})}
self.addEventListener('push',event=>event.waitUntil((async()=>{let p;try{p=event.data.json()}catch{return}if(!/^[a-f0-9]{64}$/.test(p.id||''))return;try{if(await seen(p.id))return}catch{}const actions=Array.isArray(p.actions)?p.actions.filter(a=>['approve','reject','view','snooze'].includes(a.action)).slice(0,typeof Notification.maxActions==='number'?Notification.maxActions:2):[];await self.registration.showNotification(String(p.title||'Tradeomatic AI').slice(0,180),{body:String(p.body||'Open analysis to review.').slice(0,1800),tag:p.id,renotify:false,icon:'/icon-192.png',badge:'/icon-192.png',data:{event_id:p.id},actions});try{await seen(p.id,true)}catch{}})()));
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const id=event.notification.data?.event_id;if(!/^[a-f0-9]{64}$/.test(id||''))return;const action=['approve','reject','view','snooze'].includes(event.action)?event.action:'view';const url=new URL('/',self.location.origin);url.searchParams.set('notification',id);url.searchParams.set('action',action);await self.clients.openWindow(url.href)})())});
